    subtotal = sum(qty * unit for qty, unit in lines)
    print("DEBUG subtotal", subtotal)
    # TODO: handle stacking discounts
    if discount:
        subtotal -= subtotal * discount
    # old = sum(q * u for q, u in lines)
    # return old
    return round(subtotal, 2)
